import{_ as r,h as o,i as e,c as n,v as l,p as s,x as t,m as p,e as E,S as h}from"./chunks/framework.Dvtg8yj2.js";const I=JSON.parse('{"title":"逆光刻 ILT 与曲线掩模","description":"","frontmatter":{"title":"逆光刻 ILT 与曲线掩模","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ilt-curvilinear.md","filePath":"llm/ilt-curvilinear.md","lastUpdated":1788454257000}'),d={name:"llm/ilt-curvilinear.md"};function c(A,a,B,T,m,P){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="逆光刻-ilt-与曲线掩模" tabindex="-1">逆光刻 ILT 与曲线掩模 <a class="header-anchor" href="#逆光刻-ilt-与曲线掩模" aria-label="Permalink to &quot;逆光刻 ILT 与曲线掩模&quot;">​</a></h1><div class="epigraph"><p>若正向成像是已知的，掩模应当由目标晶圆图形反演得到。曼哈顿折线只是写入工具的历史约束，不是光学的本征基。</p><footer>—— 对照逆成像思路与 Mack 对掩模频谱、透镜通带的讨论</footer></div><p>模型基 <a href="/llm/opc">OPC</a> 在多边形边上做局部移动，搜索空间仍是「设计图形的形变」。逆光刻（Inverse Lithography Technology, ILT）把掩模当成像素或水平集，直接对前向模型求逆：给定目标轮廓与工艺窗口，反解透过率图，再把它收成可写的几何。曲线掩模是这条逆的自然输出——透镜通带里有效的形状本来就不是直角。长期卡住的不是算法存在性，而是 <a href="/llm/multibeam-mask-writer">VSB 写掩模</a> 的炮数与全芯片算力；多束机台与 GPU 把这两道闸松开之后，曲线 ILT 才从热区补丁变成可讨论的量产选项。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>正向问题：掩模 \\(M\\) 经成像算子 \\(\\mathcal{I}\\) 得到晶圆轮廓 \\(I=\\mathcal{I}(M)\\)。OPC 限制 \\(M\\) 与设计同拓扑、边只能法向挪。热区——紧孔、二维拐角、切层末端——需要的修正往往不在这个流形上：助条该长成自由曲线，主图形该变成光学上更圆的「岛」。继续切碎曼哈顿边，变量数目爆炸，MRC 尖角丛生，而空中像改善有限，因为高频直角会被 NA 滤掉。</p><p>逆问题病态：许多掩模对应几乎相同的低通空中像，噪声和模型误差会被放大。必须正则化（平滑、MRC、剂量/焦点鲁棒项），否则解在像素噪声里打转。问题因此是：在可制造约束下求一个稳定的逆，而不是求数学上的精确逆。</p><h3 id="曼哈顿是写入基-不是成像基" tabindex="-1">曼哈顿是写入基，不是成像基 <a class="header-anchor" href="#曼哈顿是写入基-不是成像基" aria-label="Permalink to &quot;曼哈顿是写入基，不是成像基&quot;">​</a></h3><p>VSB 电子束按矩形炮拼接。OPC 输出直角多边形，是为了让炮数可估、数据量可传。光学却在频率域工作：有效信息在截止频率以内。用大量小矩形逼近一条光滑等高线，是把写入工具的基强加给成像。曲线掩模改用样条或曲边多边形描述同一条等高线，数据量按控制点计，写入时间在多束机上近似与图形复杂度解耦。</p><p><span class="marginnote">「曲线」不是为了好看。目标是让掩模频谱把能量放在透镜能传的模态上，并让工艺窗口带变窄。若曲线化之后 PV-band 没有改善，只是增加了掩模数据体积，那就还不该上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>ILT 的计算核是：像素化或水平集表示 \\(M\\)，用可微的成像与抗蚀剂模型求轮廓或强度相对目标的损失，反传更新 \\(M\\)，再投影到 MRC（最小宽度/间距、曲率、面积）。鲁棒 ILT 在剂量、焦点、掩模误差的若干扰动上同时求损失，避免只在名义点漂亮。输出先是灰度或水平集，再提取曲线轮廓，做掩模厂能接受的分档与简化。</p><p>全芯片纯 ILT 的变量数是 OPC 碎片的数量级之上。实践是分层：SMO 定光源；常规 OPC 覆盖大部分；ILT 打在窗口不够的热区，或对关键层做「全芯片曲线但有简化预算」。GPU 把前向与梯度从按周变成按夜，见 <a href="/llm/computational-litho-gpu">cuLitho</a>；没有这条算力，ILT 只能当研究。</p><h3 id="从像素到可写曲线" tabindex="-1">从像素到可写曲线 <a class="header-anchor" href="#从像素到可写曲线" aria-label="Permalink to &quot;从像素到可写曲线&quot;">​</a></h3><p>像素解不能直接写。要提取等值线、合并碎片、限制曲率、对齐到电子束网格，并保证相邻曝光场拼接处连续。MRC 对曲线是新语言：不再只是边平行间距，而是曲率半径、颈宽、孔的圆度。掩模检测（AIM、SEM）也要从直角边算法改成曲边计量。ILT 项目失败，常常失败在这条后处理链，而不是优化没收敛。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>损失对掩模像素的梯度，本质上是伴随成像：把晶圆上的轮廓误差反投到掩模平面。低通特性意味着梯度本身是光滑的，这解释了为什么无约束 ILT 会倾向曲线——梯度下降在通带内走，不会稳定出尖锐直角，除非正则化强行推回曼哈顿。加入曼哈顿约束等于在解上再投影一次，损失通常回升，窗口变差；这正是「曲线有光学收益」的来源。</p><p>与 SRAF 的关系：ILT 会自发「长出」助条状结构，因为它们降低损失。不必先跑一套规则助条再 OPC。坏处是助条可能违反 MRC 或在某些工艺角印出来，必须靠鲁棒项和投影把它们按住。EUV 掩模 3D 让梯度还含阴影与多层膜，曲线在不同取向上不该对称，算法若用 DUV 薄掩模伴随，会收敛到错误形状。</p><p><span class="marginnote">ILT 不是「更强的 OPC」这么一句升级。OPC 是在多边形流形上的局部搜索；ILT 换了表示与可行集。把 ILT 当 OPC 的更高迭代次数，会低估数据格式、写入与检测要改的量。</span></p><h3 id="热区-ilt-与全芯片-ilt" tabindex="-1">热区 ILT 与全芯片 ILT <a class="header-anchor" href="#热区-ilt-与全芯片-ilt" aria-label="Permalink to &quot;热区 ILT 与全芯片 ILT&quot;">​</a></h3><p>热区模式把计算和掩模复杂度限制在已知难点，集成风险低，但要有可靠的热区筛选，否则漏网图形在硅上才出现。全芯片曲线追求统一窗口与统一数据路径，却把多束产能、数据准备和检测一起绑死。量产节奏通常是：先热区，再关键层全芯片，再随写入与 GPU 日历扩张。</p>',20)),(e(),s(h,null,{default:t(()=>[E(i,{id:"mermaid-58",class:"mermaid",graph:"flowchart%20TD%0A%20%20TGT%5B%22%E7%9B%AE%E6%A0%87%E8%BD%AE%E5%BB%93%20%2B%20PV%20%E6%89%B0%E5%8A%A8%22%5D%20--%3E%20LOSS%5B%22%E5%8F%AF%E5%BE%AE%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20M%5B%22%E5%83%8F%E7%B4%A0%20%2F%20%E6%B0%B4%E5%B9%B3%E9%9B%86%E6%8E%A9%E6%A8%A1%22%5D%20--%3E%20FWD%5B%22%E6%88%90%E5%83%8F%20%2B%20%E8%83%B6%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20FWD%20--%3E%20LOSS%0A%20%20LOSS%20--%3E%20ADJ%5B%22%E4%BC%B4%E9%9A%8F%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20ADJ%20--%3E%20M%0A%20%20M%20--%3E%20PROJ%5B%22MRC%20%2F%20%E6%9B%B2%E7%8E%87%E6%8A%95%E5%BD%B1%22%5D%0A%20%20PROJ%20--%3E%20CURV%5B%22%E6%8F%90%E5%8F%96%E6%9B%B2%E7%BA%BF%E5%A4%9A%E8%BE%B9%E5%BD%A2%22%5D%0A%20%20CURV%20--%3E%20MB%5B%22%E5%A4%9A%E6%9D%9F%E5%86%99%E5%85%A5%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>ILT 吃模型误差的方式与 OPC 不同：它会把模型漏洞拟合成奇怪的掩模纹理，看起来损失很低，硅上却是新热区。校准与验证必须用独立的晶圆数据，而不是同一套紧凑模型的自洽。随机胶效应仍不在可微均值模型里，曲线掩模不能替代 <a href="/llm/euv-resist">抗蚀剂与剂量</a> 的统计工作。</p><p>掩模数据量、解密传输、以及知识产权边界（曲线特征难以人工解读，却更难做传统「多边形等价」比对）都是 TAPOUT 合同的一部分。没有多束机，曲线 ILT 会把 VSB 写入时间拉到不可接受；有多束机而无 GPU，全芯片逆也排不进日历。三者要一起成熟。</p><p><span class="marginnote">引用 ILT 收益时写清：相对的是规则 OPC 还是模型 OPC，层别，是否含蚀刻，以及掩模写入是 VSB 还是多束。只报热区 clips 的窗口，不能外推到全芯片产率。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ILT 对前向成像求正则化的逆，表示从多边形边变成像素或水平集。</li><li>曲线是通带内梯度下降的自然几何；曼哈顿主要是 VSB 写入遗留约束。</li><li>可制造性取决于 MRC 投影、曲边检测与多束写入，而不只是优化器。</li><li>全芯片 ILT 受算力与数据路径限制，量产多从热区切入。</li><li>模型误差会被逆问题放大，必须用独立硅数据验证。</li><li>与 SMO、OPC、多束、GPU 是同一条链上的不同闸门。</li><li>出处：逆光刻与曲线掩模公开文献；Mack 成像框架。</li></ul>',6))])}const L=r(d,[["render",c]]);export{I as __pageData,L as default};
